/**
 * @summary Initiate vehicle ownership transfer
 */
export const getTransferVehicleUrl = (vehicleId: number) => {
  return `/api/vehicles/${vehicleId}/transfer`;
};

export const transferVehicle = async (
  vehicleId: number,
  transferVehicleBody: TransferVehicleBody,
  options?: RequestInit,
): Promise<OwnershipRecord> => {
  return customFetch<OwnershipRecord>(getTransferVehicleUrl(vehicleId), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(transferVehicleBody),
  });
};

export const getTransferVehicleMutationOptions = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof transferVehicle>>,
    TError,
    { vehicleId: number; data: BodyType<TransferVehicleBody> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof transferVehicle>>,
  TError,
  { vehicleId: number; data: BodyType<TransferVehicleBody> },
  TContext
> => {
  const mutationKey = ["transferVehicle"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof transferVehicle>>,
    { vehicleId: number; data: BodyType<TransferVehicleBody> }
  > = (props) => {
    const { vehicleId, data } = props ?? {};

    return transferVehicle(vehicleId, data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type TransferVehicleMutationResult = NonNullable<
  Awaited<ReturnType<typeof transferVehicle>>
>;
export type TransferVehicleMutationBody = BodyType<TransferVehicleBody>;
export type TransferVehicleMutationError = ErrorType<unknown>;

